"""Incremental, sourced golf shot-reference library with a local filming worksheet.
No downloaded broadcast footage, generated player facts, or simulated trajectory.
"""
import html,re,json,hashlib,datetime
from common import ORIGIN
E=html.escape
GUIDES={
 'approach':('Approach shot','Keep the ball and the space above the target in frame. A tight crop of the golfer can lose the flight immediately after impact.','Record from a stable position behind the ball, clear of the swing. Keep recording through the finish; do not pan from the clubhead to the green.','Compare the visible launch with the visible flight, then mark where the ball becomes too small to follow. A broadcast cut to the green is a separate camera view; do not join those views into a continuous tracer.'),
 'tee':('Tee shot','Leave room above the golfer and along the intended start line. A ball can leave the image while the golfer remains fully visible.','Set the phone before the player begins. Keep it stationary and use the original clip rather than a screen recording or a zoomed social repost.','Separate the direction at launch from any later curve you can actually see. A landing shown by another camera does not prove a continuous tracked path from the tee.'),
 'bunker':('Bunker shot','Keep both the ball position and the near edge of the bunker visible. Flying sand can briefly hide the ball at impact.','Place the camera safely outside the playing area and protect the lens from sand. Hold the frame steady instead of following the sand plume.','Check the first visible ball position after the sand clears. If visibility is interrupted, keep the original video and avoid extending a tracer through an unobserved segment.'),
 'chip':('Chip shot','Include the starting ball position and the first landing area where possible. The airborne segment may be short compared with the roll.','Use a stable frame and keep the whole motion, including the finish. Avoid cropping the ball out to fill the screen with the golfer.','Distinguish the short flight from the bounce and roll. A flight overlay should not imply that the whole visible path was airborne.'),
}
def slug(row):
 return re.sub(r'[^a-z0-9]+','-',row['keyword'].lower()).strip('-')[:130]+'-'+row['evidence']['id']
def facts(row):
 v=row['evidence'];d=v['description'];f=[('Player',', '.join(p['firstName']+' '+p['lastName'] for p in v['playerVideos'])),('Shot context',GUIDES[row['kind']][0]),('Season',v['year']),('Source video length',str(v['duration'])+' seconds')]
 if v.get('roundNumber') and str(v['roundNumber']).isdigit():f.append(('Round',str(v['roundNumber'])))
 hole=v.get('holeNumber') or (re.search(r'(?:No\. |(?:par-\d )?)(\d+)(?:st|nd|rd|th) hole',d) or [None,None])[1]
 if hole:f.append(('Hole',str(hole)))
 # Only extract explicit source facts, with units and without treating them as AI measurements.
 par=re.search(r'\bpar-([345])\b',d)
 if par:f.append(('Hole par',par[1]))
 return f
def layout(template,path,title,desc,body):
 canonical=ORIGIN+path;head=template.split('</head>')[0]
 head=re.sub(r'<title>.*?</title>','<title>'+E(title)+'</title>',head)
 for attr,names in [('name',['description','twitter:title','twitter:description']),('property',['og:title','og:description','og:url'])]:
  for name in names:
   val=canonical if name=='og:url' else title if name.endswith('title') else desc
   head=re.sub(fr'(<meta {attr}="{name}" content=")[^"]*(")',lambda m:m[1]+E(val,quote=True)+m[2],head)
 head=re.sub(r'(<link rel="canonical" href=")[^"]*(")',lambda m:m[1]+canonical+m[2],head)
 graph=json.loads(re.search(r'<script type="application/ld\+json">(.*?)</script>',head).group(1))
 for item in graph['@graph']:
  if item['@type']=='WebPage':item.update({'@id':canonical+'#webpage','url':canonical,'name':title,'description':desc,'breadcrumb':{'@id':canonical+'#breadcrumb'}})
  if item['@type']=='BreadcrumbList':item.update({'@id':canonical+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':'GolfCut','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title,'item':canonical}]})
 head=re.sub(r'<script type="application/ld\+json">.*?</script>',lambda _: '<script type="application/ld+json">'+json.dumps(graph).replace('<','\\u003c')+'</script>',head)
 header=template.split('<body>')[1].split('<main')[0];footer=template[template.index('<footer>'):]
 return head+'<link rel="stylesheet" href="/shot-library.css"></head><body>'+header+'<main class="wrap"><nav class="seo-breadcrumb" aria-label="Breadcrumb"><a href="/">GolfCut</a> / <a href="/shot-library">Shot library</a></nav>'+body+'</main>'+footer.replace('</body>','<script src="/shot-library.js" defer></script></body>')
def render(template,row,related):
 v=row['evidence'];path='/shot-library/'+slug(row);kind,framing,record,review=GUIDES[row['kind']];who=', '.join(p['firstName']+' '+p['lastName'] for p in v['playerVideos']);title=row['keyword']+' — filming notes | GolfCut'
 desc=f"Filming notes for {row['keyword']}. Source details, framing checks and a GolfCut tracer worksheet for your own footage."
 factlist=''.join('<dt>'+E(k)+'</dt><dd>'+E(str(val))+'</dd>' for k,val in facts(row))
 body=f'''<section class="sub-hero"><p class="eyebrow">GOLF VIDEO REFERENCE · {E(kind.upper())}</p><h1>{E(row['keyword'])}</h1><p>Use this published golf moment as a reference when planning how to record your own {kind.lower()}. Open the source video, then use the checklist below to decide what your own camera needs to capture.</p><a class="btn" href="{E(row['source_url'],quote=True)}" rel="noopener noreferrer" target="_blank">Watch the PGA TOUR source ↗</a></section>
 <article class="article-body"><h2>Reference details</h2><dl class="shot-facts">{factlist}</dl><p>These details come from the publisher’s video catalog. This page does not claim a frame-by-frame analysis of the broadcast or a GolfCut edit of it. The source link identifies the exact reference.</p>
 <h2>Plan your {kind.lower()} recording</h2><h3>Framing</h3><p>{E(framing)}</p><h3>Before pressing record</h3><p>{E(record)}</p><h3>What to check in the reference</h3><p>{E(review)}</p>
 <h2>Make a shot-by-shot viewing note</h2><p>While watching <strong>{E(who)}</strong> in the linked reference, record where impact occurs, when the ball stops being visible and whether the camera cuts. The worksheet runs in this browser; its entries are not uploaded or used to infer a trajectory.</p>
 <form class="shot-notes" data-shot="{v['id']}"><label>Impact time (seconds)<input name="impact" type="number" min="0" step="0.01" placeholder="Enter from the video"></label><label>Last visible ball (seconds)<input name="visible" type="number" min="0" step="0.01" placeholder="Enter from the video"></label><label>Camera view<select name="camera"><option value="unknown">Not checked yet</option><option value="steady">One steady view</option><option value="moving">Camera moves or zooms</option><option value="cut">Cut to another camera</option></select></label><label>What should your own recording show?<textarea name="notes" rows="4" placeholder="Ball visibility, framing, obstructions, flight versus roll…"></textarea></label><button class="btn" type="submit">Check my recording plan</button><output aria-live="polite"></output><button type="button" class="text-link" data-download-notes>Download my notes</button></form>
 <h2>Try a tracer on your own clip</h2><ol><li>Record a single shot using the framing checks above. Keep an unedited original.</li><li>Trim the clip to 30 seconds or less for the online trial.</li><li>Open GolfCut’s trial and mark the impact moment and starting ball position.</li><li>Review the returned result. Detection may fail or contain errors; do not use an overlay as a distance measurement or proof of landing location.</li></ol><p><a class="btn" href="/try-tracer">Try your own golf video</a> <a class="text-link" href="/golf-shot-tracer">How the golf tracer works</a></p><p>The linked broadcast stays on the publisher’s site. Use footage you own or have permission to edit. A professional broadcast may use multiple cameras and tracking equipment; a phone clip has different visibility limits.</p>
 <h2>Related shot references</h2><ul>'''+''.join(f'<li><a href="/shot-library/{slug(x)}">{E(x["keyword"])}</a></li>' for x in related)+'''</ul><p><a href="/shot-library">Browse the golf shot library</a></p></article>'''
 return layout(template,path,title,desc,body)
CSS='''.shot-facts{display:grid;grid-template-columns:minmax(100px,1fr) 2fr;gap:10px 20px}.shot-facts dt{font-weight:700}.shot-facts dd{margin:0}.shot-notes{display:grid;gap:18px;padding:24px;border:1px solid #cdd8d2;border-radius:16px}.shot-notes label{display:grid;gap:8px}.shot-notes input,.shot-notes textarea,.shot-notes select,.library-search{width:100%;max-width:100%;font:inherit;padding:12px;border:1px solid #a9b8b0;border-radius:8px;box-sizing:border-box;background:white;color:#123e32}.shot-notes output{white-space:pre-wrap}.article-body li{margin:12px 0}.sub-hero h1{overflow-wrap:anywhere}.library-links{display:grid;gap:12px;padding:0;list-style:none}@media(max-width:600px){.sub-hero h1{font-size:clamp(24px,7vw,38px)}.shot-notes{padding:16px}.shot-facts{grid-template-columns:1fr}.shot-facts dd{margin-bottom:12px}}'''
JS='''document.querySelectorAll('.shot-notes').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form),a=d.get('impact'),b=d.get('visible');let msg=[];if(a===''||b==='')msg.push('Enter observed times before calculating a visibility window.');else if(+b<+a)msg.push('Last-visible time must be at or after impact.');else msg.push('Observed visibility window: '+(+b-+a).toFixed(2)+' seconds. This is your note, not an automated measurement.');if(d.get('camera')==='cut')msg.push('Use one continuous camera view for your own tracer clip; do not infer a path across a cut.');if(d.get('camera')==='moving')msg.push('For your own recording, use a stable camera and check that the ball remains in frame.');if(d.get('camera')==='unknown')msg.push('Check whether the source changes camera views.');msg.push('Keep your original clip. Review the overlay for errors before sharing.');form.querySelector('output').textContent=msg.join('\\n');});form.querySelector('[data-download-notes]').addEventListener('click',()=>{const data=Object.fromEntries(new FormData(form));const b=new Blob([JSON.stringify({reference:location.href,...data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='golf-shot-notes-'+form.dataset.shot+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});});document.querySelectorAll('[data-library-search]').forEach(input=>input.addEventListener('input',()=>{const q=input.value.toLowerCase();document.querySelectorAll('.library-links li').forEach(li=>li.hidden=!li.textContent.toLowerCase().includes(q));}));'''
